type SepaInput = { entryPrice: number; stopLossPrice: number; pivotPrice: number; aboveMa50Ma200: boolean; ma200Uptrend: boolean; near52wHigh: boolean; patternType: PatternType; vcpContractions?: number; lastContractionPct?: number; volumeDryup: boolean; marketRegime: MarketRegime };
type SepaResult = { score: number; grade: "A+" | "A" | "B" | "C / FOMO"; riskPct: number; chasingPct: number; breakdown: { label: string; points: number; max: number; detail: string }[]; feedback: string };
type DisplayUnit = "USD" | "EUR" | "GBP" | "PERCENT";
type Account = { id: string; name: string; currency: "USD" | "EUR" | "GBP"; startingCapital: number; color: string };
type LocalTrade = { id: number; accountId?: string; pivotPrice: number; aboveMa50Ma200: boolean; ma200Uptrend: boolean; near52wHigh: boolean; patternType: PatternType; vcpContractions?: number; lastContractionPct?: number; volumeDryup: boolean; marketRegime: MarketRegime; sepaScore: number; sepaGrade: SepaResult["grade"]; chasingPct: number; sepaRiskPct: number; symbol: string; assetType: AssetType; direction: Direction; setup: string; entryPrice: number; exitPrice: number; positionSize: number; stopLoss: number; takeProfit: number; riskTradePct: number; chartUrl: string; notes: string; openedAt: string; closedAt: string; grossPnl: number; tradingFee: number; swapFee: number; pnl: number; riskAmount: number; rrRatio: number; rMultiple: number; result: Result; isComplete: boolean };
type TradeForm = { symbol: string; pivotPrice: string; aboveMa50Ma200: boolean; ma200Uptrend: boolean; near52wHigh: boolean; patternType: PatternType; vcpContractions: string; lastContractionPct: string; volumeDryup: boolean; marketRegime: MarketRegime; assetType: AssetType; direction: Direction; setup: string; entryPrice: string; exitPrice: string; positionSize: string; stopLoss: string; takeProfit: string; riskTradePct: string; tradingFee: string; swapFee: string; openedAt: string; closedAt: string; chartUrl: string; notes: string };

